<script setup lang="ts">
import {ref,shallowRef,watch,computed,onScopeDispose,nextTick} from 'vue'
import {ApiError,errorMessage,IdentityChanged,onIdentityChange} from '@/core/http'
import {projectId,currentProject,can,session} from '@/core/session'
import {useDeviceGuard,isDeviceScopeCurrent} from './use-device-guard'
import {readDeviceLocation,decodeDeviceLocation,prepareDeviceLocation,writeDeviceLocation,locationMatches,type DeviceLocationPoint,type DeviceLocationIntent} from './device-location-api'
import AsyncState from '@/ui/AsyncState.vue'
import DeviceLocationMapPicker from './DeviceLocationMapPicker.vue'
import DevicePositionMap from './DevicePositionMap.vue'
import type {LocationMapPoint} from './location-map-draft'
import {devicesApi} from './api'
import {readLocationDetails,writeLocationDetails,prepareLocationDetails,hasLocationDetails,emptyLocationAddress,locationAddress,sameLocationAddress,addressFields,type LocationSnapshot,type LocationAddress,type LocationDetailsIntent} from './device-location-details-api'
import {readLocationObservation,type LocationObservation} from './device-location-observation-api'
const props=withDefaults(defineProps<{deviceId:string;editLabel?:string;useTypePolicy?:boolean;disabled?:boolean;reference?:boolean}>(),{useTypePolicy:false,disabled:false,reference:false}),capture=useDeviceGuard(()=>props.deviceId)
const emit=defineEmits<{locked:[value:boolean]}>(),observation=shallowRef<LocationObservation>(),notice=ref('')
const point=shallowRef<LocationSnapshot>(),snapshot=shallowRef<LocationSnapshot>(),intent=shallowRef<DeviceLocationIntent|LocationDetailsIntent>(),current=shallowRef<LocationSnapshot>()
const mapPicker=shallowRef<InstanceType<typeof DeviceLocationMapPicker>>()
const referenceMap=shallowRef<InstanceType<typeof DevicePositionMap>>()
const addressDraft=ref<LocationAddress>(emptyLocationAddress()),latitudeText=ref(''),longitudeText=ref(''),addressSearchDirty=ref(false)
const addressLabels=[['province','省份'],['city','城市'],['district','区 / 县'],['street','街道'],['building','建筑'],['unit','单元'],['floor','楼层'],['room','房号']] as const
const hasAddress=computed(()=>point.value&&addressFields.some(key=>point.value?.[key]))
const regionText=computed(()=>point.value?['province','city','district','street'].map(key=>point.value?.[key as keyof LocationAddress]??'').join(''):'')
const loading=ref(false),readError=ref(''),denied=ref(false),open=ref(false),longitude=ref<number>(),latitude=ref<number>(),busy=ref(false),error=ref(''),review=ref<'unknown'|'rejected'>()
const readable=computed(()=>can('device:read')&&!denied.value),baseWritable=computed(()=>readable.value&&can('device:update')&&currentProject.value?.status==='ACTIVE'),writable=computed(()=>baseWritable.value&&!props.disabled&&(!props.useTypePolicy||observation.value?.source==='LEGACY_MANUAL'||observation.value?.source==='MANUAL')),locked=computed(()=>busy.value||open.value||!!review.value)
const effectivePoint=computed(()=>!props.useTypePolicy?point.value:observation.value&&['LEGACY_MANUAL','MANUAL','REPORTED_PROPERTY'].includes(observation.value.source)?{longitude:observation.value.longitude,latitude:observation.value.latitude}:undefined)
let generation=0,sequence=0,uiSequence=0,disposed=false,readController:AbortController|undefined,writeController:AbortController|undefined
const scope=()=>({project:projectId.value,device:props.deviceId})
async function readSnapshot(selected:ReturnType<typeof scope>,signal:AbortSignal):Promise<LocationSnapshot>{
 if(!props.reference)return decodeDeviceLocation(await readDeviceLocation(selected,signal))
 try{return await readLocationDetails(selected,signal)}catch(cause){if(!(cause instanceof ApiError)||cause.status!==404)throw cause}
 const [point,device]=await Promise.all([readDeviceLocation(selected,signal),devicesApi.read(selected.project,selected.device,signal)])
 return {...decodeDeviceLocation(point),address:device.location??null}
}
function isDetailedIntent(value:DeviceLocationIntent|LocationDetailsIntent):value is LocationDetailsIntent{return 'expectedAddressToken' in value&&'address' in value}
function still(check:()=>void,g:number){return !disposed&&generation===g&&isDeviceScopeCurrent(check)}
function reset(){generation++;sequence++;uiSequence++;readController?.abort();writeController?.abort();point.value=undefined;observation.value=undefined;notice.value='';snapshot.value=undefined;intent.value=undefined;current.value=undefined;longitude.value=undefined;latitude.value=undefined;loading.value=false;busy.value=false;open.value=false;readError.value='';error.value='';review.value=undefined;denied.value=false;addressDraft.value=emptyLocationAddress();latitudeText.value='';longitudeText.value='';addressSearchDirty.value=false}
function unavailable(cause:unknown){reset();denied.value=true;readError.value=errorMessage(cause)}
async function read(){
 if(!readable.value||!projectId.value||!props.deviceId)return
 const g=generation,seq=++sequence,check=capture(),selected=scope();readController?.abort();readController=new AbortController();loading.value=true;readError.value='';point.value=undefined
 try{const [bytes,effective]=await Promise.all([readSnapshot(selected,readController.signal),props.useTypePolicy?readLocationObservation(selected,readController.signal):Promise.resolve(undefined)]);const result=bytes;if(still(check,g)&&seq===sequence&&readable.value){point.value=result;observation.value=effective;return result}}
 catch(cause){if(still(check,g)&&seq===sequence&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&[401,403,404].includes(cause.status))unavailable(cause);else readError.value=errorMessage(cause)}}
 finally{if(generation===g&&seq===sequence)loading.value=false}
}
function close(){uiSequence++;open.value=false;error.value='';snapshot.value=undefined;current.value=undefined;longitude.value=undefined;latitude.value=undefined;addressDraft.value=emptyLocationAddress();latitudeText.value='';longitudeText.value='';addressSearchDirty.value=false}
function usePoint(value:LocationSnapshot){snapshot.value=Object.freeze({...value});longitude.value=value.longitude??undefined;latitude.value=value.latitude??undefined;addressDraft.value=locationAddress(value);addressSearchDirty.value=false;latitudeText.value=value.latitude==null?'':String(value.latitude);longitudeText.value=value.longitude==null?'':String(value.longitude)}
async function edit(){
 if(!writable.value||busy.value||loading.value)return
 close();open.value=true;const u=uiSequence
 if(review.value){await refreshCurrent();return}
 const value=await read();if(u===uiSequence&&open.value&&writable.value&&value)usePoint(value)
}
async function refreshCurrent(){
 const original=intent.value;if(!original||busy.value||!readable.value)return
 const g=generation,u=uiSequence,check=capture();writeController?.abort();writeController=new AbortController();busy.value=true;current.value=undefined;error.value=''
 try{const [bytes,effective]=await Promise.all([readSnapshot(original,writeController.signal),props.useTypePolicy?readLocationObservation(original,writeController.signal):Promise.resolve(undefined)]);const value=bytes;if(still(check,g)&&u===uiSequence&&readable.value){current.value=value;point.value=value;observation.value=effective}}
 catch(cause){if(still(check,g)&&u===uiSequence&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&[401,403].includes(cause.status))unavailable(cause);else error.value=cause instanceof ApiError&&cause.status===404?'暂未读到该设备当前坐标，请继续核对；不会重新提交。':errorMessage(cause)}}
 finally{if(g===generation)busy.value=false}
}
async function reopenReview(){if(!review.value||!readable.value||busy.value)return;close();open.value=true;await refreshCurrent()}
function finishReview(){if(!current.value||busy.value)return;const unconfirmed=review.value==='unknown';point.value=current.value;review.value=undefined;intent.value=undefined;close();notice.value=unconfirmed?'已采用当前坐标；原写入结果仍未确认，未重新提交。':'已读取当前坐标；本次被拒绝的写入未重试。'}
function continueEditing(){if(!current.value||!writable.value||busy.value)return;usePoint(current.value);review.value=undefined;intent.value=undefined;current.value=undefined;error.value=''}
function referenceCoordinates(kind:'latitude'|'longitude',value:string){if(busy.value||review.value)return;referenceMap.value?.cancel();const parsed=/^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?$/.test(value)?Number(value):undefined;if(kind==='latitude'){latitudeText.value=value;latitude.value=parsed}else{longitudeText.value=value;longitude.value=parsed}}
function referencePoint(value:LocationMapPoint){if(!open.value||!snapshot.value||busy.value||review.value||!writable.value)return;longitude.value=value.longitude;latitude.value=value.latitude;longitudeText.value=String(value.longitude);latitudeText.value=String(value.latitude)}
function addressChanged(search=false){referenceMap.value?.cancel();if(search)addressSearchDirty.value=true}
function findAddress(){if(addressSearchDirty.value&&addressDraft.value.address){addressSearchDirty.value=false;referenceMap.value?.locateName(addressDraft.value.address)}}
function applyMapDraft(value:LocationMapPoint,draftSession:number){if(open.value&&snapshot.value&&writable.value&&!busy.value&&!review.value&&draftSession===uiSequence){longitude.value=value.longitude;latitude.value=value.latitude}}
async function focusMapDraft(){const u=uiSequence;await nextTick();if(u===uiSequence&&open.value&&snapshot.value&&writable.value&&!busy.value&&!review.value)props.reference?referenceMap.value?.focusPoint():mapPicker.value?.focusDraft(u)}
async function save(clear=false){
 if(!writable.value||!snapshot.value||busy.value||review.value)return
 let chosen:DeviceLocationIntent|LocationDetailsIntent
 try{chosen=props.reference&&hasLocationDetails(snapshot.value)?prepareLocationDetails(scope(),snapshot.value,clear?null:longitude.value??null,clear?null:latitude.value??null,clear?emptyLocationAddress():addressDraft.value):prepareDeviceLocation(scope(),snapshot.value,clear?null:longitude.value??null,clear?null:latitude.value??null);if(!clear&&(longitude.value===undefined||latitude.value===undefined)&&!(hasLocationDetails(snapshot.value)&&longitude.value===undefined&&latitude.value===undefined))throw new Error('经纬度需要同时填写')}catch(cause){error.value=errorMessage(cause);return}
 const g=generation,u=uiSequence,check=capture();intent.value=chosen;review.value='unknown';busy.value=true;error.value='';writeController=new AbortController();let accepted=false
 try{
  const result=isDetailedIntent(chosen)?await writeLocationDetails(chosen,writeController.signal):decodeDeviceLocation(await writeDeviceLocation(chosen,writeController.signal));accepted=true
  if(!still(check,g)||u!==uiSequence||!writable.value)return
  const expected={longitude:chosen.longitude,latitude:chosen.latitude,version:String(BigInt(chosen.version)+1n)}
  const expectedAddress=isDetailedIntent(chosen)?chosen.address:undefined
  if(!locationMatches(result,expected)||expectedAddress&&(!hasLocationDetails(result)||addressFields.some(key=>result[key]!==expectedAddress[key])))throw new Error('坐标保存回执与本次选择不符，请核对当前坐标')
  const [actualBytes,effective]=await Promise.all([readSnapshot(chosen,writeController.signal),props.useTypePolicy?readLocationObservation(chosen,writeController.signal):Promise.resolve(undefined)])
  const actual=actualBytes
  if(!still(check,g)||u!==uiSequence||!baseWritable.value)return
  if(!locationMatches(actual,result)||isDetailedIntent(chosen)&&!sameLocationAddress(actual,result))throw new Error('当前坐标已发生变化，请重新核对')
  point.value=actual;observation.value=effective;review.value=undefined;intent.value=undefined;close()
 }catch(cause){if(still(check,g)&&u===uiSequence&&!(cause instanceof IdentityChanged)){
  if(cause instanceof ApiError&&[401,403].includes(cause.status)){unavailable(cause);return}
  const rejected=!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&[400,404,409,413,422,429].includes(cause.status)
  review.value=rejected?'rejected':'unknown';open.value=true;error.value=errorMessage(cause)
 }}finally{if(g===generation)busy.value=false}
}
function scopeChanged(){reset();if(readable.value)void read()}
const dispose=onIdentityChange(scopeChanged)
watch([()=>projectId.value,()=>props.deviceId,()=>session.user?.accountId,()=>can('device:read'),()=>props.useTypePolicy],scopeChanged,{immediate:true,flush:'sync'})
watch(baseWritable,allowed=>{if(!allowed&&!review.value)close()},{flush:'sync'})
watch(locked,value=>emit('locked',value),{immediate:true,flush:'sync'})
onScopeDispose(()=>{disposed=true;reset();dispose();emit('locked',false)})
</script>
<template><div class="device-location" :class="{'location-reference':reference}"><AsyncState :loading="loading" :error="readError?new Error(readError):undefined" @retry="read"><template v-if="readable"><DevicePositionMap v-if="reference&&effectivePoint?.longitude!=null&&effectivePoint?.latitude!=null" :key="`${projectId}:${deviceId}`" class="location-preview" :device-id="deviceId" :longitude="effectivePoint.longitude" :latitude="effectivePoint.latitude"/><div v-if="reference&&hasAddress" class="location-address"><p v-if="point?.address">{{point.address}}</p><p v-if="regionText&&(!point?.address||!point.address.includes(regionText))">{{regionText}}</p><div v-if="point?.building||point?.unit||point?.floor||point?.room" class="location-building"><template v-for="[key,label] in addressLabels.slice(4)" :key="key"><p v-if="point?.[key]">{{label}}: {{point[key]}}</p></template></div></div><p v-if="!reference||effectivePoint?.longitude!=null&&effectivePoint?.latitude!=null" class="location-coordinates"><template v-if="reference">{{effectivePoint?.latitude}}, {{effectivePoint?.longitude}}</template><template v-else>经度 {{effectivePoint?.longitude??'—'}} · 纬度 {{effectivePoint?.latitude??'—'}}</template></p><p v-if="useTypePolicy&&observation?.source==='REPORTED_PROPERTY'&&observation.reported" role="status">设备上报：{{observation.reported.propertyKey}} · 固定模型 {{observation.reported.modelVersionId}} · 上报版本 {{observation.reported.reportedRevision}} · 发生时间 {{observation.reported.occurredAt}}</p><p v-if="useTypePolicy&&observation?.source==='DISABLED'&&(!reference||point?.longitude!=null)" role="status">该类型已关闭地理坐标扩展；原人工坐标仍保留。</p><p v-else-if="useTypePolicy&&observation?.source==='UNAVAILABLE'" role="status">当前类型位置来源不可用，不能编辑或生成地图点。</p><p v-if="useTypePolicy&&observation?.source==='DISABLED'&&point&&(!reference||point.longitude!=null)">保留的人工经度 {{point.longitude??'—'}} · 纬度 {{point.latitude??'—'}}</p><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><div class="location-actions"><el-button v-if="review" size="small" :disabled="busy" @click="reopenReview">{{useTypePolicy?'核对原坐标写入':editLabel||'编辑地理位置'}}</el-button><el-button v-else-if="writable" :size="editLabel?'small':'default'" :disabled="!point||busy" @click="edit">{{editLabel||'编辑地理位置'}}</el-button><el-button v-if="useTypePolicy&&!reference" size="small" :disabled="busy||open" @click="read">刷新位置</el-button></div></template></AsyncState>
<el-dialog :model-value="open" :title="review?'核对当前坐标':reference?'编辑设备位置':'编辑地理位置'" :width="review?'min(520px,94vw)':'min(900px,94vw)'" class="device-location-dialog" :class="{'location-reference-dialog':reference}" :close-on-click-modal="false" destroy-on-close @close="close">
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="review"><el-alert :title="review==='unknown'?'保存结果尚未确认，只读取该设备当前坐标，不会重新提交。':'本次保存已被拒绝，请读取当前坐标后再决定是否编辑。'" type="warning" :closable="false"/><p v-if="current">当前经度 {{current.longitude??'—'}} · 当前纬度 {{current.latitude??'—'}}</p><dl v-if="reference&&current&&hasLocationDetails(current)" class="location-current-address"><dt>地址</dt><dd>{{current.address||'-'}}</dd><template v-for="[key,label] in addressLabels" :key="key"><dt>{{label}}</dt><dd>{{current[key]||'-'}}</dd></template></dl></template>
<el-alert v-else-if="useTypePolicy&&observation&&!['MANUAL','LEGACY_MANUAL'].includes(observation.source)" title="当前类型不允许人工地理坐标编辑；原人工点没有删除。" type="info" :closable="false"/><div v-else-if="snapshot" class="device-location-editor"><el-form v-if="reference" size="small" label-position="top" @submit.prevent>
<el-form-item v-if="hasLocationDetails(snapshot)" label="地址" class="location-address-input"><el-input v-model="addressDraft.address" aria-label="地址" placeholder="请输入地址" maxlength="256" :disabled="busy" @input="addressChanged(true)" @blur="findAddress"/></el-form-item>
<template v-if="hasLocationDetails(snapshot)"><el-form-item v-for="[key,label] in addressLabels" :key="key" :label="label"><el-select v-if="['province','city','district','street'].includes(key)" v-model="addressDraft[key]" filterable allow-create default-first-option clearable :reserve-keyword="false" placeholder="请选择或输入" :aria-label="label" :disabled="busy" @change="addressChanged()"><el-option v-if="addressDraft[key]" :value="addressDraft[key]!" :label="addressDraft[key]!"/></el-select><el-input v-else v-model="addressDraft[key]" :aria-label="label" maxlength="128" :disabled="busy" @input="addressChanged()"/></el-form-item></template>
<el-form-item label="纬度"><el-input :model-value="latitudeText" aria-label="纬度" inputmode="decimal" :disabled="busy" @update:model-value="referenceCoordinates('latitude',$event)" @blur="focusMapDraft"/></el-form-item><el-form-item label="经度"><el-input :model-value="longitudeText" aria-label="经度" inputmode="decimal" :disabled="busy" @update:model-value="referenceCoordinates('longitude',$event)" @blur="focusMapDraft"/></el-form-item>
</el-form><el-form v-else label-position="top"><el-form-item label="经度（WGS84）"><el-input-number v-model="longitude" aria-label="经度" :size="reference?'small':'default'" :controls-position="reference?'right':undefined" :min="-180" :max="180" :precision="6" :disabled="busy" @blur="focusMapDraft"/></el-form-item><el-form-item label="纬度（WGS84）"><el-input-number v-model="latitude" aria-label="纬度" :size="reference?'small':'default'" :controls-position="reference?'right':undefined" :min="-90" :max="90" :precision="6" :disabled="busy" @blur="focusMapDraft"/></el-form-item></el-form><DevicePositionMap v-if="reference" ref="referenceMap" :key="uiSequence" :device-id="deviceId" :longitude="longitude" :latitude="latitude" :session="uiSequence" editable :disabled="busy||!writable" @point="referencePoint"/><DeviceLocationMapPicker v-else ref="mapPicker" :key="uiSequence" :longitude="longitude" :latitude="latitude" :session="uiSequence" :disabled="busy||!writable" @select="applyMapDraft"/></div><template v-else><el-alert v-if="readError" :title="readError" type="error" :closable="false"/><p v-else>正在读取当前坐标…</p><el-button v-if="readError" @click="edit">重新读取坐标</el-button></template>
<template #footer><el-button @click="close">{{review?'关闭':'取消'}}</el-button><template v-if="review"><el-button :loading="busy" @click="refreshCurrent">读取当前坐标</el-button><el-button v-if="current&&writable" type="primary" :disabled="busy" @click="continueEditing">使用当前坐标继续编辑</el-button><el-button v-if="current" :disabled="busy" @click="finishReview">采用当前坐标并结束核对</el-button></template><template v-else><el-button :class="{'location-remove':reference}" :type="reference?'danger':undefined" :disabled="busy||!snapshot||!writable" @click="save(true)">{{reference?'移除位置':'清除坐标'}}</el-button><el-button type="primary" :loading="busy" :disabled="!snapshot||!writable" @click="save(false)">保存</el-button></template></template>
</el-dialog></div></template>
<style>.location-reference{display:flow-root;min-width:0}.location-reference .location-preview{float:right;margin:16px 0 10px 24px}.location-reference:has(.location-preview){min-height:246px}@media(max-width:767px){.location-reference .location-preview{float:none;width:100%;margin:16px 0}.location-reference:has(.location-preview){min-height:0}}.location-current-address{display:grid;grid-template-columns:70px 1fr;gap:6px 12px}.location-current-address dd{margin:0;overflow-wrap:anywhere}.location-reference .location-address{padding-top:16px;font-size:16px;line-height:24px;color:#606266;overflow-wrap:anywhere}.location-reference .location-address p{margin:0}.location-reference .location-building{margin-top:20px}.location-reference .location-address+.location-coordinates{margin-top:8px}.location-reference .location-coordinates{margin:16px 0 0;font-size:16px;line-height:24px;color:#606266;font-style:italic}.location-reference .location-actions{margin-top:16px;display:flex;gap:10px}.location-reference .location-coordinates+.location-actions{margin-top:8px}.location-reference-dialog .el-dialog__body{padding:31px 20px 36px}.location-reference-dialog .el-form-item.location-address-input{grid-column:1/-1}.location-reference-dialog .el-select{width:100%}.location-reference-dialog .el-select__wrapper{min-height:32px}.location-reference-dialog .el-form-item:nth-last-child(-n+2){margin-bottom:0}.location-reference-dialog .location-remove{order:-1;margin-right:auto}.location-reference-dialog .el-form-item{margin-bottom:16px}.location-reference-dialog .device-location-editor{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.location-reference-dialog .el-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-content:start;gap:0 20px}.location-reference-dialog .el-form-item{min-width:0;margin-bottom:16px}.location-reference-dialog .el-form-item__label{font-size:14px;line-height:22px;margin-bottom:10px;color:#606266}.device-location-dialog.location-reference-dialog .el-input-number{width:100%}.location-reference-dialog .el-dialog__footer{padding-top:20px}.location-reference-dialog .el-dialog__footer .el-button{height:40px;padding:12px 20px;font-size:14px}.location-reference-dialog .device-position-map{height:460px}@media(max-width:600px){.location-reference-dialog .device-location-editor,.location-reference-dialog .el-form{grid-template-columns:minmax(0,1fr)}}.device-location-editor{display:grid;grid-template-columns:minmax(200px,260px) minmax(0,1fr);gap:24px}@media(max-width:600px){.device-location-editor{grid-template-columns:minmax(0,1fr);gap:12px}}.device-location-dialog{max-width:calc(100vw - 32px)}.device-location-dialog .el-dialog__body{max-height:calc(85dvh - 130px);overflow:auto}.device-location-dialog .el-input-number{width:260px;max-width:100%}.device-location-dialog .el-dialog__footer{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}.device-location-dialog .el-dialog__footer .el-button+.el-button{margin-left:0}.device-location-dialog .el-alert{margin-bottom:12px}</style>
